{
  "findings": [
    {
      "check_id": "CKV_AWS_55",
      "title": "S3 Bucket Public Access Block is missing",
      "resource": "aws_s3_bucket.document_storage",
      "severity": "HIGH",
      "explanation": "The S3 bucket 'document_storage' is referenced in aws_s3_bucket_public_access_block but its declaration is missing, potentially allowing public access if it's not properly configured elsewhere."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "document_storage" {
  bucket = "document-storage-bucket"
  acl    = "private"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

resource "aws_s3_bucket_public_access_block" "document_storage" {
  bucket = aws_s3_bucket.document_storage.id
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}",
  "fix_summary": "Added the missing aws_s3_bucket 'document_storage' with private ACL, versioning enabled, and server-side encryption by default to prevent potential public access and data loss."
}
